1550	function countConsecutivePassing(evaluations) {
1551	  let best = 0;
1552	  let current = 0;
1553	  for (const evaluation of evaluations) {
1554	    if (evaluation.scored && evaluation.ok) {
1555	      current += 1;
1556	      best = Math.max(best, current);
1557	    } else {
1558	      current = 0;
1559	    }
1560	  }
1561	  return best;
1562	}
