1931	async function main() {
1932	  const options = parseArgs(process.argv.slice(2));
1933	  if (options.help) {
1934	    console.log(usage());
1935	    return;
1936	  }
1937	  if (!options.relayReport || !options.uiSamples) {
1938	    throw new Error("--relay-report and --ui-samples are required");
1939	  }
1940	  const relayReport = readJSON(options.relayReport);
1941	  const relayReportErrors = validateProofReport(relayReport, { sourcePath: options.relayReport });
1942	  if (relayReportErrors.length > 0) {
1943	    throw new Error(`relay report contract failed before UI comparison:\n${relayReportErrors.join("\n")}`);
1944	  }
1945	  const report = buildRenderedUIReport({
1946	    relayReport,
1947	    uiSamples: readJSONL(options.uiSamples),
1948	    maxUiLagMs: options.maxUiLagMs,
1949	    proofRunID: proofRunIDForReportPath(options.jsonOut || options.summaryOut || options.uiSamples),
1950	  });
1951	  writeReportFiles(report, options);
1952	  process.stdout.write(`${JSON.stringify({
1953	    ok: report.summary.ok,
1954	    summary: report.summary,
1955	    relayReport: report.relayReport,
1956	    reportPath: options.jsonOut || null,
1957	    summaryPath: options.summaryOut || null,
1958	    failures: report.failures.slice(0, 20),
1959	  }, null, 2)}\n`);
1960	  if (options.failOnDiff && !report.summary.ok) {
1961	    process.exitCode = 1;
1962	  }
1963	}
1964	
1965	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
