469	        } else {
470	            // Dock proof is deliberately single-path: rendered rows come from
471	            // the Dock root payload. If that payload is missing, leave the row
472	            // dump empty so strict proof fails instead of using a second oracle.
473	            dockRows = []
474	        }
475	        let dockRowsCapturedAt = codexDockISO8601Now()
476	        let dockSweep = includeDockSweep ? checkpointDockSweep(rootValue: rootValue) : nil
477	        let detail = visibleDetail(
