525	            let frame = DisplayedUIFrame(element.frame)
526	            let key = [
527	                element.identifier,
528	                element.label,
529	                element.displayedUIStringValue,
530	                String(format: "%.1f", frame.minX),
531	                String(format: "%.1f", frame.minY),
532	                String(format: "%.1f", frame.width),
533	                String(format: "%.1f", frame.height),
534	            ].joined(separator: "|")
535	            guard seen.insert(key).inserted else {
536	                continue
537	            }
538	            snapshots.append(
539	                DisplayedUIVisibleElementSnapshot(
540	                    identifier: element.identifier,
541	                    elementType: "\(element.elementType)",
542	                    label: element.label,
543	                    value: element.displayedUIStringValue,
544	                    frame: frame
545	                )
546	            )
547	            if snapshots.count >= limit {
548	                break
549	            }
550	        }
551	        return snapshots
552	    }
