554	    private func checkpointDockSweep(rootValue: String) -> DisplayedUIDockSweep {
555	        let startedAt = codexDockISO8601Now()
556	        let expectedRootRows = dockRootRowCount(rootValue)
557	        let maxSteps = 30
558	
559	        // Dock checkpoint proof uses the same rendered row payload as normal
560	        // sampling. Do not add a second row-discovery path here; missing payload
561	        // is a proof failure, not a reason to reconstruct UI truth another way.
562	        if let rootRows = dockRowsFromRootValue(rootValue) {
563	            let reason = expectedRootRows.map { rootRows.count >= $0 ? "expectedRowsReached" : "rootRowsIncomplete" }
564	                ?? "expectedRowsReached"
565	            return DisplayedUIDockSweep(
566	                startedAt: startedAt,
567	                finishedAt: codexDockISO8601Now(),
568	                stepCount: 0,
569	                maxSteps: maxSteps,
570	                stopReason: reason,
571	                expectedRootRows: expectedRootRows,
572	                rows: rootRows
573	            )
574	        }
575	
576	        if rootValue == "not-visible" || expectedRootRows == 0 || isDockEmptyStateVisible() {
577	            return DisplayedUIDockSweep(
578	                startedAt: startedAt,
579	                finishedAt: codexDockISO8601Now(),
580	                stepCount: 0,
581	                maxSteps: maxSteps,
582	                stopReason: "expectedRowsReached",
583	                expectedRootRows: expectedRootRows,
584	                rows: []
585	            )
586	        }
587	
588	        return DisplayedUIDockSweep(
589	            startedAt: startedAt,
590	            finishedAt: codexDockISO8601Now(),
591	            stepCount: 0,
592	            maxSteps: maxSteps,
593	            stopReason: "rootRowsMissing",
594	            expectedRootRows: expectedRootRows,
595	            rows: []
596	        )
597	    }
