664	    private func checkpointDetailSweep() -> DisplayedUIDetailSweep {
665	        let startedAt = codexDockISO8601Now()
666	        var messageCardIDs: [String] = []
667	        var requestCardIDs: [String] = []
668	        var messageCards: [DisplayedUIElementSnapshot] = []
669	        var requestElements: [DisplayedUIElementSnapshot] = []
670	        var seenMessageCardIDs = Set<String>()
671	        var seenRequestCardIDs = Set<String>()
672	        var seenMessageSnapshots = Set<String>()
673	        var seenRequestSnapshots = Set<String>()
674	        var expectedMessageRows: Int?
675	        var lastVisibleIdentifier: String?
676	        var stableTailCount = 0
677	        var stepCount = 0
678	        let deadline = Date().addingTimeInterval(20)
679	
680	        func appendUnique(_ source: [String], to target: inout [String], seen: inout Set<String>) {
681	            for value in source where seen.insert(value).inserted {
682	                target.append(value)
683	            }
684	        }
685	
686	        func appendUniqueSnapshots(
687	            _ source: [DisplayedUIElementSnapshot],
688	            to target: inout [DisplayedUIElementSnapshot],
689	            seen: inout Set<String>
690	        ) {
691	            for value in source where seen.insert(value.identifier).inserted {
692	                target.append(value)
693	            }
694	        }
695	
696	        for _ in 0..<30 {
697	            if Date() >= deadline {
698	                break
699	            }
700	            stepCount += 1
701	            guard let detail = visibleDetail(includeRequestElements: true, includeMessageElements: true) else {
702	                break
703	            }
704	            if expectedMessageRows == nil {
705	                expectedMessageRows = detailMessageCount(detail.messageListValue)
706	            }
707	            appendUnique(detail.messageCardIDs, to: &messageCardIDs, seen: &seenMessageCardIDs)
708	            appendUnique(detail.requestCardIDs, to: &requestCardIDs, seen: &seenRequestCardIDs)
709	            appendUniqueSnapshots(detail.messageCards, to: &messageCards, seen: &seenMessageSnapshots)
710	            appendUniqueSnapshots(detail.requestElements, to: &requestElements, seen: &seenRequestSnapshots)
711	
712	            if let expectedMessageRows, messageCardIDs.count >= expectedMessageRows {
713	                break
714	            }
715	
716	            let currentLast = (detail.messageCardIDs + detail.requestCardIDs).last
717	            if currentLast == nil {
718	                if let expectedMessageRows, messageCardIDs.count < expectedMessageRows {
719	                    dragDetailPageUp()
720	                    RunLoop.current.run(until: Date().addingTimeInterval(0.25))
721	                    continue
722	                }
723	                break
724	            }
725	            if currentLast == lastVisibleIdentifier {
726	                stableTailCount += 1
727	                if stableTailCount >= 2 {
728	                    break
729	                }
730	            } else {
731	                stableTailCount = 0
732	            }
733	            lastVisibleIdentifier = currentLast
734	            dragDetailPageUp()
735	            RunLoop.current.run(until: Date().addingTimeInterval(0.25))
736	        }
737	
738	        return DisplayedUIDetailSweep(
739	            startedAt: startedAt,
740	            finishedAt: codexDockISO8601Now(),
741	            stepCount: stepCount,
742	            expectedMessageRows: expectedMessageRows,
743	            messageCardIDs: messageCardIDs,
744	            requestCardIDs: requestCardIDs,
745	            messageCards: messageCards,
746	            requestElements: requestElements
747	        )
748	    }
