761	    private func visibleDockRows() -> [DisplayedUIDockRow] {
762	        guard !isDockEmptyStateVisible() else {
763	            return []
764	        }
765	        let rowElements = dockRowElementCandidates()
766	        guard !isDockEmptyStateVisible() else {
767	            return []
768	        }
769	        var rowByIdentifier: [String: XCUIElement] = [:]
770	        for element in rowElements {
771	            let identifier = element.identifier
772	            guard identifier.hasPrefix("codexdock.dock.row."),
773	                  !identifier.contains(".action.") else {
774	                continue
775	            }
776	            let frame = element.frame
777	            guard isVisibleForTap(frame) else {
778	                continue
779	            }
780	            if let existing = rowByIdentifier[identifier],
781	               existing.frame.width * existing.frame.height >= frame.width * frame.height {
782	                continue
783	            }
784	            rowByIdentifier[identifier] = element
785	        }
786	
787	        let rows = rowByIdentifier.map { identifier, row in
788	            DisplayedUIDockRow(
789	                identifier: identifier,
790	                value: row.displayedUIStringValue,
791	                label: row.label,
792	                frame: DisplayedUIFrame(row.frame)
793	            )
794	        }
795	        return rows.sorted(by: displayedUITopToBottomOrder)
796	    }
