802	    private func dockRowElement(id: String, candidates: [XCUIElement]?) -> XCUIElement? {
803	        // Dock rows intentionally expose rich child text. The row button and
804	        // child labels can share the same projection-backed ID, and XCUITest
805	        // can report the row role as Button or PopUpButton across runs. Resolve
806	        // exact-ID matches by visible size so proof code uses the row container.
807	        let elements = candidates ?? dockRowElementCandidates(id: id)
808	        return elements
809	            .filter { $0.identifier == id }
810	            .filter { isVisibleForTap($0.frame) }
811	            .max { left, right in
812	                (left.frame.width * left.frame.height) < (right.frame.width * right.frame.height)
813	            }
814	    }
