824	    private func dockRowElementCandidates(_ matches: (String) -> Bool) -> [XCUIElement] {
825	        // SwiftUI can report the same Dock row as Button or PopUpButton across
826	        // simulator runs, and XCTest predicate queries can record a failure when
827	        // a legitimate archive/delete transition leaves zero rows. Enumerate
828	        // first, then filter by the stable accessibility identifier contract.
829	        return descendants(matching: .any)
830	            .allElementsBoundByIndex
831	            .filter { matches($0.identifier) }
832	    }
