855	    private func visibleDetail(
856	        includeRequestElements: Bool = true,
857	        includeMessageElements: Bool = false
858	    ) -> DisplayedUIDetail? {
859	        let startedAt = codexDockISO8601Now()
860	        let root = displayedUIWaitForElement(identifierPrefix: "codexdock.session.root.", timeout: 0.1)
861	        guard let root, root.exists else {
862	            return nil
863	        }
864	        let rootValue = root.displayedUIStringValue
865	        let rootCapturedAt = codexDockISO8601Now()
866	        // Capture scalar state before expensive row enumeration so proof lag is
867	        // based on when the UI exposed the state, not XCUITest scan overhead.
868	        let headerValue = optionalStringValue(id: AutomationID.Session.header.rawValue)
869	        let headerCapturedAt = codexDockISO8601Now()
870	        let messageListValue = optionalStringValue(id: AutomationID.Session.messageList.rawValue)
871	        let messageListCapturedAt = codexDockISO8601Now()
872	        let messageIDsFromList = messageCardIdentifiers(fromMessageListValue: messageListValue)
873	        let messageCards: [DisplayedUIElementSnapshot]
874	        let messageCardsCapturedAt: String
875	        if includeMessageElements {
876	            messageCards = elementSnapshots(prefix: "codexdock.session.message.", in: root)
877	            messageCardsCapturedAt = codexDockISO8601Now()
878	        } else {
879	            // The detail list is the timing-critical live-update witness. It
880	            // exposes ordered projection IDs directly, so normal samples must
881	            // not broad-scan every child card before recording displayed state.
882	            messageCards = []
883	            messageCardsCapturedAt = messageListCapturedAt
884	        }
885	        let requestElements = includeRequestElements
886	            ? elementSnapshots(prefix: "codexdock.session.request.", in: root)
887	            : []
888	        let requestElementsCapturedAt = includeRequestElements ? codexDockISO8601Now() : messageCardsCapturedAt
889	        return DisplayedUIDetail(
890	            startedAt: startedAt,
891	            finishedAt: codexDockISO8601Now(),
892	            rootIdentifier: root.identifier,
893	            rootCapturedAt: rootCapturedAt,
894	            rootValue: rootValue,
895	            headerCapturedAt: headerCapturedAt,
896	            headerValue: headerValue,
897	            messageListCapturedAt: messageListCapturedAt,
898	            messageListValue: messageListValue,
899	            messageCardsCapturedAt: messageCardsCapturedAt,
900	            messageCardIDs: uniquePreservingOrder(messageIDsFromList + messageCards.map(\.identifier)),
901	            requestElementsCapturedAt: requestElementsCapturedAt,
902	            requestCardIDs: requestElements.map(\.identifier),
903	            messageCards: messageCards,
904	            requestElements: requestElements
905	        )
906	    }
