941	    private func elementSnapshots(elements: [XCUIElement], prefix: String) -> [DisplayedUIElementSnapshot] {
942	        var snapshots: [DisplayedUIElementSnapshot] = []
943	        var seen = Set<String>()
944	        for element in elements {
945	            let identifier = element.identifier
946	            guard identifier.hasPrefix(prefix) else {
947	                continue
948	            }
949	            guard seen.insert(identifier).inserted else {
950	                continue
951	            }
952	            let value = element.displayedUIStringValue
953	            let label = element.label
954	            let frame = DisplayedUIFrame(element.frame)
955	            snapshots.append(
956	                DisplayedUIElementSnapshot(
957	                    identifier: identifier,
958	                    capturedAt: codexDockISO8601Now(),
959	                    value: value,
960	                    label: label,
961	                    frame: frame
962	                )
963	            )
964	            if snapshots.count >= 120 {
965	                break
966	            }
967	        }
968	        // Displayed-UI proof must preserve visual order. Sorting by identifier
969	        // hides the exact class of newest-first bugs this harness exists to catch.
970	        return snapshots.sorted(by: displayedUITopToBottomOrder)
971	    }
