980	
981	    private func displayedUITopToBottomOrder(
982	        _ leftFrame: DisplayedUIFrame,
983	        _ rightFrame: DisplayedUIFrame,
984	        _ leftIdentifier: String,
985	        _ rightIdentifier: String
986	    ) -> Bool {
987	        let verticalTolerance = 1.0
988	        if abs(leftFrame.minY - rightFrame.minY) > verticalTolerance {
989	            return leftFrame.minY < rightFrame.minY
990	        }
991	        if leftFrame.minX != rightFrame.minX {
992	            return leftFrame.minX < rightFrame.minX
993	        }
994	        return leftIdentifier < rightIdentifier
995	    }
