997	    private func isVisibleForTap(_ frame: CGRect) -> Bool {
998	        guard frame.width > 1, frame.height > 1 else {
999	            return false
1000	        }
1001	        let window = windows.firstMatch
1002	        let visibleFrame = window.exists ? window.frame : frame
1003	        let bottomLimit = tabBars.firstMatch.exists
1004	            ? tabBars.firstMatch.frame.minY - 1
1005	            : visibleFrame.maxY - 1
1006	        return frame.midY >= visibleFrame.minY + 1
1007	            && frame.midY <= bottomLimit
1008	            && frame.maxX > visibleFrame.minX
1009	            && frame.minX < visibleFrame.maxX
1010	    }
1011	}
