224	function validateProofReport(report, {
225	  validators = loadProofSchemas(),
226	  sourcePath = "<report>",
227	} = {}) {
228	  const kind = report?.kind;
229	  const validate = validators.get(kind);
230	  const errors = [];
231	  if (!validate) {
232	    errors.push(`unsupported proof report kind ${kind || "missing"} at ${sourcePath}`);
233	    return errors;
234	  }
235	  if (!validate(report)) {
236	    for (const error of validate.errors || []) {
237	      errors.push(`${sourcePath}${error.instancePath || ""}: ${error.message}`);
238	    }
239	  }
240	  errors.push(...semanticProofErrors(report).map((message) => `${sourcePath}: ${message}`));
241	  return errors;
242	}
