90	function parseSemicolonValue(value) {
91	  const result = {};
92	  for (const part of String(value || "").split(";")) {
93	    const trimmed = part.trim();
94	    if (!trimmed) {
95	      continue;
96	    }
97	    const equals = trimmed.indexOf("=");
98	    if (equals === -1) {
99	      result[trimmed] = true;
100	      continue;
101	    }
102	    result[trimmed.slice(0, equals).trim()] = trimmed.slice(equals + 1).trim();
103	  }
104	  return result;
105	}
